class Solution {
public:
    int minSwaps(string s) {
        int mismatched = 0;
        for (char c : s) {
            if (c == '[') mismatched++;
            else if (mismatched > 0) mismatched--;
        }
        return (mismatched + 1) / 2;
    }
};

class Solution {
    public int minSwaps(String s) {
        int mismatched = 0;
        for (char c : s.toCharArray()) {
            if (c == '[') mismatched++;
            else if (mismatched > 0) mismatched--;
        }
        return (mismatched + 1) / 2;
    }
}

var minSwaps = function(s) {
  let mismatched = 0;
  for (const c of s) {
    if (c === '[') mismatched++;
    else if (mismatched > 0) mismatched--;
  }
  return Math.floor((mismatched + 1) / 2);
};
